int of_address_to_resource ( const struct device_node * dev , int index , struct resource * r ) { const __be32 * addrp ; u64 size ; unsigned int flags ; const char * name = NULL ; addrp = of_get_address ( dev , index , & size , & flags ) ; of_property_read_string_index ( dev , "reg-names" , index , & name ) ; return __of_address_to_resource ( dev , addrp , size , flags , name , r ) ; } 